use egui::{Color32, Pos2, Stroke, Vec2};
pub fn apply(ctx:&egui::Context,dark:bool) { let (canvas,surface,muted,ink,primary)=if dark {(Color32::from_rgb(20,27,24),Color32::from_rgb(22,30,27),Color32::from_rgb(30,41,37),Color32::from_rgb(243,241,234),Color32::from_rgb(217,230,220))}else{(Color32::from_rgb(244,241,233),Color32::from_rgb(255,254,250),Color32::from_rgb(235,236,229),Color32::from_rgb(23,33,28),Color32::from_rgb(31,77,58))};let mut v=if dark {egui::Visuals::dark()}else{egui::Visuals::light()};v.override_text_color=Some(ink);v.panel_fill=canvas;v.window_fill=surface;v.extreme_bg_color=surface;v.widgets.noninteractive.bg_fill=muted;v.widgets.inactive.bg_fill=muted;v.selection.bg_fill=primary;ctx.set_visuals(v); }
pub fn brand(ui:&mut egui::Ui) {let (r,_)=ui.allocate_exact_size(Vec2::new(32.0,32.0),egui::Sense::hover());let p=ui.painter();let c=ui.visuals().selection.bg_fill;p.rect_filled(r,7.0,c);let white=if ui.visuals().dark_mode {Color32::from_rgb(20,27,24)}else{Color32::WHITE};p.line_segment([Pos2::new(r.left()+7.0,r.center().y),Pos2::new(r.center().x,r.top()+7.0)],Stroke::new(2.5,white));p.line_segment([Pos2::new(r.center().x,r.top()+7.0),Pos2::new(r.right()-7.0,r.center().y)],Stroke::new(2.5,white));p.line_segment([Pos2::new(r.left()+10.0,r.center().y),Pos2::new(r.left()+10.0,r.bottom()-7.0)],Stroke::new(2.5,white));p.line_segment([Pos2::new(r.left()+10.0,r.bottom()-7.0),Pos2::new(r.right()-9.0,r.bottom()-7.0)],Stroke::new(2.5,white)); }
